import { join } from "node:path";

/**
 * @typedef {{
 *   env: (name: unknown) => Promise<string | undefined>,
 *   fileExists: (path: unknown) => Promise<boolean>
 * }} AuthContext
 */

const importNodeModule = (specifier) => import(specifier);
const runtimeContextPath = join(
  process.cwd(),
  "tests/fixtures/npm-static/node_modules/auth-context-runtime/index.js",
);

/** @returns {Promise<AuthContext>} */
export async function defaultProviderAuthContext() {
  const source = await importNodeModule(runtimeContextPath);
  return source.createContext();
}
